import { ResponseError } from "../../errors.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
/* CreateAcls Request (Version: 0) => [creations]; creations => resource_type resource_name principal host operation permission_type */
export function createRequest(creations) { return Writer.create().appendArray(creations, (w, c) => { w.appendInt8(c.resourceType).appendString(c.resourceName, false).appendString(c.principal, false).appendString(c.host, false).appendInt8(c.operation).appendInt8(c.permissionType); }, false, false); }
/* CreateAcls Response (Version: 0) => throttle_time_ms [results]; results => error_code error_message */
export function parseResponse(_, apiKey, apiVersion, reader) { const errors = []; const response = { throttleTimeMs: reader.readInt32(), results: reader.readArray((r, i) => { const result = { errorCode: r.readInt16(), errorMessage: r.readNullableString(false) }; if (result.errorCode)
        errors.push([`/results/${i}`, [result.errorCode, result.errorMessage]]); return result; }, false, false) }; if (errors.length)
    throw new ResponseError(apiKey, apiVersion, Object.fromEntries(errors), response); return response; }
export const api = createAPI(30, 0, createRequest, parseResponse, false, false);
